-- Add rank metadata to the existing roles/capabilities; no existing account is reassigned.
CREATE TABLE staff_rank_profiles (
 id TEXT PRIMARY KEY,label TEXT NOT NULL,level INTEGER NOT NULL,description TEXT NOT NULL,
 permissions_json TEXT NOT NULL CHECK(json_valid(permissions_json) AND json_type(permissions_json)='array'),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),updated_by TEXT REFERENCES users(id),updated_at INTEGER NOT NULL
);
CREATE TABLE staff_rank_assignments (
 user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
 rank_id TEXT NOT NULL REFERENCES staff_rank_profiles(id),
 permissions_json TEXT NOT NULL CHECK(json_valid(permissions_json) AND json_type(permissions_json)='array'),
 expires_at INTEGER,reason TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
 assigned_by TEXT NOT NULL REFERENCES users(id),updated_at INTEGER NOT NULL
);
CREATE INDEX staff_rank_members ON staff_rank_assignments(rank_id,user_id);
CREATE TABLE staff_chat_reads (
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,target TEXT NOT NULL,
 message_id TEXT NOT NULL REFERENCES staff_chat_messages(id) ON DELETE CASCADE,
 message_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(user_id,target)
);
CREATE INDEX staff_chat_dm_recent ON staff_chat_messages(recipient_id,author_id,created_at DESC,id DESC);
CREATE INDEX staff_chat_channel_recent ON staff_chat_messages(channel,created_at DESC,id DESC) WHERE recipient_id IS NULL;
